{"message":"装飾フレームを自由形状で作成します。中央は開口のままで、外形は滑らかな有機曲線（炎・蔓状）を四隅に配し、四隅は部位別に定義して右上だけ後で差し替え可能にします。サイズは幅65×奥行95×厚み12mm以内、色はマットな灰色(#7A7A7A)にします。家ではなく独立パーツとしてXYに寝かせるのでsceneはobjectになります。以下で1つの自由形状プログラム(model-1)を追加します。","changes":[{"path":"scene","value":"object"},{"path":"program.upsert","value":{"id":"model-1","name":"有機装飾フレーム（分割可能）","x":20,"y":20,"color":"#7A7A7A","size":[65,95,12],"source":"// Organic decorative frame for XY-facing placement
// Units: mm. Final piece fits within 65x95x12 bounding box.
let base=box([65,95,2]);
// create four corner flourish tubes using stroke-like tube approximations
// Top-left flourish
let tlPath=[];
tlPath.push([6,88,2]);
tlPath.push([4,78,4]);
tlPath.push([10,68,6]);
tlPath.push([18,58,8]);
tlPath.push([26,52,6]);
tlPath.push([20,48,4]);
let tl=tube(tlPath,3.5);
// Top-right flourish (separate part to allow later replacement)
let trPath=[];
trPath.push([39,88,2]);
trPath.push([45,78,4]);
trPath.push([53,70,6]);
trPath.push([57,60,8]);
trPath.push([51,54,6]);
trPath.push([46,50,4]);
let tr=tube(trPath,3.8);
// Bottom-left flourish
let blPath=[];
blPath.push([6,7,2]);
blPath.push([8,18,4]);
blPath.push([14,28,6]);
blPath.push([22,36,8]);
blPath.push([30,42,6]);
blPath.push([24,46,4]);
let bl=tube(blPath,3.6);
// Bottom-right flourish
let brPath=[];
brPath.push([39,7,2]);
brPath.push([46,18,4]);
brPath.push([54,30,6]);
brPath.push([58,38,8]);
brPath.push([52,44,6]);
brPath.push([46,48,4]);
let br=tube(brPath,3.6);
// central irregular rim (open center) built by extruding an organic outline and subtracting inner hole
const outer=[[2,6],[8,4],[16,2],[26,2],[38,6],[48,10],[60,20],[62,30],[62,65],[58,78],[50,86],[40,92],[28,92],[14,86],[6,78],[2,66]];
const inner=[[20,26],[30,22],[42,24],[50,34],[50,58],[40,68],[30,72],[18,64]];
let rim=extrude(outer,4);
let hole=move(extrude(inner,6),[0,0,0.5]);
rim=subtract(rim,hole);
// add small organic droplets and bridges to create internal cutouts and connection points
let drop1=tube([[32,50,4],[34,44,6],[30,40,8]],1.6);
let drop2=tube([[18,62,4],[22,56,6],[20,50,7]],1.4);
let drop3=tube([[48,34,4],[46,28,6],[42,24,7]],1.2);
// smoothly join rim and corner flourishes
let frame=union(rim,tl,tr,bl,br,drop1,drop2,drop3);
// give slight back thickness and cap to reach 12mm max height
let backPlate=move(box([61,91,4]),[2,2,0]);
frame=union(frame,backPlate);
// final scale/fit safety: ensure within bounds (already designed to fit)
return frame;"}},{"path":"name","value":"15cmぬいのおうち（オブジェクト：装飾フレーム追加）"}]}
